// =========================================================
// HELPERS
// =========================================================

function formatRelativeTime(input?: number | string): string {
  if (input === undefined || input === null) return "Recently";
  const ts = typeof input === "number" ? input : new Date(input).getTime();
  if (!Number.isFinite(ts)) return "Recently";
  const now = Date.now();
  const diffMs = now - ts;
  if (diffMs < 0) return "Just now";
  const diffMin = Math.floor(diffMs / 60000);
  const diffHr = Math.floor(diffMs / 3600000);
  if (diffMin < 1) return "Just now";
  if (diffMin < 60) return `${diffMin} min ago`;
  if (diffHr < 6) return `${diffHr} hr ago`;
  const date = new Date(ts);
  const nowDate = new Date(now);
  const isSameDay =
    date.getFullYear() === nowDate.getFullYear() &&
    date.getMonth() === nowDate.getMonth() &&
    date.getDate() === nowDate.getDate();
  if (isSameDay) return `Today, ${date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}`;
  const yesterday = new Date(now);
  yesterday.setDate(nowDate.getDate() - 1);
  const isYesterday =
    date.getFullYear() === yesterday.getFullYear() &&
    date.getMonth() === yesterday.getMonth() &&
    date.getDate() === yesterday.getDate();
  if (isYesterday) return "Yesterday";
  if (diffMs > 7 * 24 * 3600000) return date.toLocaleDateString([], { month: "short", day: "numeric" });
  return date.toLocaleDateString([], { weekday: "short" });
}

