// =========================================================
// MODULE GRID CARD
// =========================================================

function ModuleGridCard({ module }: { module: SubModule }) {
  const Icon = moduleIconMap[module.path];
  const navigate = useNavigate();

  return (
    <Tilt3D intensity={12}>
      <motion.div
        whileHover={{ y: -8 }}
        whileTap={{ scale: 0.97 }}
        className="h-full"
        onClick={() => navigate(module.path)}
      >
        <div
          className={cn(
            "relative h-full rounded-[1.75rem] bg-gradient-to-br from-[#1e1b4b]/90 to-[#0f0a2e]/90 backdrop-blur-xl border-2 border-purple-500/30",
            "shadow-[0_0_25px_rgba(168,85,247,0.2)] hover:shadow-[0_0_40px_rgba(168,85,247,0.5)] hover:border-purple-400/60 transition-all duration-300",
            "cursor-pointer p-7 flex flex-col"
          )}
        >
          <div
            className={cn(
              "flex h-20 w-20 items-center justify-center rounded-2xl shadow-lg bg-gradient-to-br",
              module.gradient
            )}
          >
            {Icon ? <Icon className="w-10 h-10 text-white" /> : <span className="text-4xl">{module.emoji}</span>}
          </div>

          <h4 className="mt-6 text-xl sm:text-2xl font-extrabold text-white leading-snug">{module.title}</h4>
          <p className="mt-2 text-base text-purple-200/70 leading-snug line-clamp-2">{module.description}</p>

          {module.premium && (
            <span className="absolute -bottom-3 -right-3 flex h-11 w-11 items-center justify-center rounded-full bg-gradient-to-br from-amber-400 to-orange-500 shadow-lg border-2 border-white/20">
              <Crown className="w-6 h-6 text-white" />
            </span>
          )}
        </div>
      </motion.div>
    </Tilt3D>
  );
}

